from collections import deque

def diameter(g):
    best = 0
    for s in g:
        dist = {s: 0}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in g[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    q.append(v)
        best = max(best, max(dist.values()))
    return best

def link(g, a, b):
    g[a].append(b)
    g[b].append(a)

rows, cols = 2, 4
N = rows * cols
mesh = {i: [] for i in range(N)}
for r in range(rows):
    for c in range(cols):
        u = r * cols + c
        if r + 1 < rows:
            link(mesh, u, (r + 1) * cols + c)
        if c + 1 < cols:
            link(mesh, u, r * cols + c + 1)
mesh_deg = max(len(v) for v in mesh.values())
mesh_diam = diameter(mesh)
mesh_bis = min(rows, cols)

tree = {i: [] for i in range(N)}
for i in range(1, N):
    link(tree, i, (i - 1) // 2)
tree_deg = max(len(v) for v in tree.values())
tree_diam = diameter(tree)
tree_bis = 1

n = 3
Nc = 2 ** n
cube = {i: [] for i in range(Nc)}
for i in range(Nc):
    for b in range(n):
        j = i ^ (1 << b)
        if j > i:
            link(cube, i, j)
cube_deg = max(len(v) for v in cube.values())
cube_diam = diameter(cube)
cube_bis = Nc // 2

for v in [mesh_deg, mesh_diam, mesh_bis, tree_deg, tree_diam, tree_bis, cube_deg, cube_diam, cube_bis]:
    print(v)
